import java.util.*;
public class Main {
    static class UserEntity {
        String id="7"; String username="alice"; String password="s3cret";
    }
    static class UserDTO {
        String id; String username;
        public String toString(){ return "UserDTO{id="+id+", username="+username+"}"; }
    }
    static UserDTO toDto(UserEntity e){
        UserDTO d=new UserDTO();
        d.id=e.id; d.username=e.username;   // password intentionally NOT copied
        return d;
    }
    public static void main(String[] a){
        UserEntity e=new UserEntity();
        UserDTO d=toDto(e);
        System.out.println("DTO: "+d);
        System.out.println("dto field count (no password): "+d.getClass().getDeclaredFields().length);
        System.out.println("entity password leaked? "+(d.toString().contains("s3cret")));
    }
}
